import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { AlertTriangle, ArrowLeft, Calculator, CalendarClock, CheckCircle2, ChevronRight, FileCheck2, FileText, Landmark, Plus, ReceiptIndianRupee, ShieldCheck, X } from 'lucide-react'
import { useEffect, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from 'react'
import { Link } from 'react-router-dom'
import { apiGet, apiPost, apiPut } from '@/lib/api'
import { formatINR, localDateKey } from '@/lib/utils'
import VisualLoadingState from '@/components/laundry/VisualLoadingState'

type Tab = 'overview' | 'liabilities' | 'returns' | 'policies'
type ReturnRecord = { id: string; returnType: string; periodStart: string; periodEnd: string; dueDate: string; transactionCount: number; amountPaise: number; state: string; evidence?: string; acknowledgement?: string }
type IconType = 'health' | 'liability' | 'calendar' | 'return' | 'evidence' | 'attention' | 'calculator' | 'policy' | 'complete'
const today = localDateKey()
const monthStart = `${today.slice(0, 7)}-01`
const moneyPaise = (value: string) => Math.max(0, Math.round(Number(value || 0) * 100))
const money = (paise?: number) => formatINR((paise || 0) / 100)
const returnName = (type: string) => ({ TDS_138: 'Salary TDS return', TDS_140: 'Resident non-salary TDS return', TCS_143: 'Income-tax TCS return', GSTR_8: 'GST ECO TCS return' }[type] || type)
const returnForm = (type: string) => ({ TDS_138: 'Form 138', TDS_140: 'Form 140', TCS_143: 'Form 143', GSTR_8: 'GSTR-8' }[type] || type)
const policyName = (key: string) => key.includes('CONTRACTOR') ? 'Contractor payments' : key.includes('PROFESSIONAL') ? 'Professional services' : key.includes('TECHNICAL') ? 'Technical services' : key.includes('COMMISSION') ? 'Commission / brokerage' : key.includes('RENT_EQUIPMENT') ? 'Equipment rent' : key.includes('RENT_PROPERTY') ? 'Property rent' : key.includes('GOODS_PURCHASE') ? 'Purchase of goods' : key.includes('ECOMMERCE') ? 'E-commerce participant' : key.includes('GST-ECO') ? 'Marketplace GST TCS' : 'Configured statutory policy'

export default function LaundryStatutoryFinance() {
  const client = useQueryClient()
  const [tab, setTab] = useState<Tab>('overview')
  const [selectedReturn, setSelectedReturn] = useState<ReturnRecord | null>(null)
  const [liabilityFilter, setLiabilityFilter] = useState<'all' | 'TDS' | 'TCS'>('all')
  const [postingMode, setPostingMode] = useState<'tds' | 'gst-tcs' | 'income-tcs' | null>(null)
  const [policyBuilder, setPolicyBuilder] = useState(false)
  const dashboard = useQuery({ queryKey: ['finance-statutory-dashboard', monthStart, today], queryFn: () => apiGet<any>(`/finance/statutory-dashboard?from=${monthStart}&to=${today}`) })
  const transactions = useQuery({ queryKey: ['finance-statutory-transactions', monthStart, today], queryFn: () => apiGet<any[]>(`/finance/statutory-transactions?from=${monthStart}&to=${today}`) })
  const policies = useQuery({ queryKey: ['finance-income-tax-tcs-policies'], queryFn: () => apiGet<any[]>('/finance/tcs/policies') })
  const refresh = () => { void client.invalidateQueries({ queryKey: ['finance-statutory-dashboard'] }); void client.invalidateQueries({ queryKey: ['finance-statutory-transactions'] }); void client.invalidateQueries({ queryKey: ['finance-income-tax-tcs-policies'] }); void client.invalidateQueries({ queryKey: ['finance-command-center'] }) }
  const prepare = useMutation({ mutationFn: (payload: { returnType: string; periodStart: string; periodEnd: string }) => apiPost('/finance/statutory-returns/prepare', payload), onSuccess: refresh })
  if (dashboard.isLoading) return <Loading />
  if (dashboard.error || !dashboard.data) return <Failure message={dashboard.error instanceof Error ? dashboard.error.message : 'The statutory controls could not load.'} />
  const data = dashboard.data
  const command = data.commandCenter || { health: 'CONTROLLED', attention: [], timeline: [], policyDistribution: data.transactions.byPolicy || [], dueSoonCount: 0, missingEvidenceCount: 0 }
  const filtered = (transactions.data || []).filter((transaction) => liabilityFilter === 'all' || (liabilityFilter === 'TDS' ? transaction.entity === 'finance_tds_transaction' : transaction.entity === 'finance_tcs_transaction'))
  const health = healthPresentation(command.health)
  return <main className="animate-in fade-in slide-in-from-bottom-2 space-y-5 pb-10 duration-500">
    <header className="overflow-hidden rounded-[28px] border border-[#35216f]/25 bg-[radial-gradient(circle_at_86%_14%,rgba(218,210,255,.34),transparent_28%),linear-gradient(135deg,#2d1e65,#664cf0)] px-5 py-6 text-white shadow-[0_20px_54px_rgba(81,56,207,.22)] md:px-7 md:py-7">
      <div className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><Link to="/laundry/finance" className="inline-flex items-center gap-1.5 text-xs font-bold text-[#b4ded8] transition hover:text-white"><ArrowLeft className="h-3.5 w-3.5" /> Finance workspace</Link><div className="mt-5 flex items-start gap-3"><FinanceMark type="health" inverse /><div><p className="text-[10px] font-extrabold uppercase tracking-[.2em] text-[#a8ddd5]">Finance control room</p><h1 className="mt-1 font-display text-3xl font-semibold tracking-[-.045em] md:text-4xl">Know what needs action.</h1><p className="mt-2 max-w-xl text-sm leading-6 text-[#cbdedc]">Posted liabilities, return readiness and evidence—kept separate from revenue and never presented as a government filing without proof.</p></div></div></div><div className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/10 p-3 backdrop-blur-sm"><StatusDot tone={health.tone} /><div><p className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[#a8ddd5]">Finance health</p><p className="mt-1 text-sm font-bold">{health.label}</p><p className="mt-0.5 text-xs text-[#cbdedc]">{health.detail}</p></div></div></div>
      <nav aria-label="Finance control views" className="mt-6 flex max-w-full gap-1 overflow-x-auto rounded-2xl border border-white/10 bg-[#0b202d]/35 p-1.5">{([['overview', 'Overview'], ['liabilities', 'Liabilities'], ['returns', 'Returns'], ['policies', 'Policies']] as Array<[Tab, string]>).map(([value, label]) => <button key={value} type="button" onClick={() => setTab(value)} className={`min-w-max rounded-xl px-4 py-2 text-xs font-extrabold transition ${tab === value ? 'bg-white text-[#17353c] shadow-sm' : 'text-[#c7dfdc] hover:bg-white/10 hover:text-white'}`}>{label}</button>)}</nav>
    </header>
    {tab === 'overview' ? <><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon="liability" label="Recorded liability" value={money(data.liabilities.totalPaise)} note="TDS + TCS posted for this period" tone="violet" /><Metric icon="calendar" label="Due soon" value={String(command.dueSoonCount)} note="Returns due within seven days" tone="amber" /><Metric icon="return" label="Return actions" value={String(data.openReturns)} note="Not acknowledged or accepted" tone="blue" /><Metric icon="evidence" label="Evidence gaps" value={String(command.missingEvidenceCount)} note="Submitted records lacking reference" tone="rose" /></section><section className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><CommandPanel eyebrow="Next actions" title={command.attention.length ? `${command.attention.length} thing${command.attention.length === 1 ? '' : 's'} need attention` : 'You are up to date'} icon="attention">{command.attention.length ? <div className="space-y-2">{command.attention.slice(0, 4).map((item: any) => <button key={item.id} type="button" onClick={() => setSelectedReturn(data.returns.find((record: ReturnRecord) => record.id === item.returnId) || null)} className="group flex w-full items-center gap-3 rounded-2xl border border-[#273d4a]/8 bg-[#fbfcfc] px-3 py-3 text-left transition hover:border-[#6c4df6]/30 hover:bg-[#f8f6ff]"><FinanceMark type={item.kind === 'OVERDUE' ? 'attention' : item.kind === 'EVIDENCE_REQUIRED' ? 'evidence' : 'calendar'} /><div className="min-w-0 flex-1"><p className="text-sm font-extrabold text-[#17353c]">{item.label}</p><p className="mt-0.5 text-xs text-[#657681]">{item.detail}</p></div><span className="inline-flex items-center gap-1 text-xs font-bold text-[#5d42e8]">{item.action}<ChevronRight className="h-3.5 w-3.5" /></span></button>)}</div> : <SmartEmpty type="complete" title="No compliance action required today" detail="There are no overdue returns or evidence gaps in the current statutory workspace." />}</CommandPanel><CommandPanel eyebrow="Quick actions" title="Create a controlled record" icon="calculator"><div className="grid gap-2">{([{ label: 'Post TDS', detail: 'Use a covered source transaction', icon: 'tds' as const }, { label: 'Post GST TCS', detail: 'Net taxable marketplace supply', icon: 'gst-tcs' as const }, { label: 'Post income-tax TCS', detail: 'Only from an approved policy', icon: 'income-tcs' as const }]).map((item) => <button key={item.icon} type="button" onClick={() => setPostingMode(item.icon)} className="group flex items-center gap-3 rounded-2xl border border-[#273d4a]/8 bg-[#fbfcfc] px-3 py-3 text-left transition hover:border-[#1f736d]/30 hover:bg-[#f4fbf8]"><FinanceMark type={item.icon === 'tds' ? 'liability' : 'policy'} /><div className="min-w-0 flex-1"><p className="text-sm font-extrabold text-[#17353c]">{item.label}</p><p className="mt-0.5 text-xs text-[#657681]">{item.detail}</p></div><Plus className="h-4 w-4 text-[#39786f]" /></button>)}</div></CommandPanel></section><section className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><LiabilityPicture data={data} onFilter={setLiabilityFilter} onOpen={() => setTab('liabilities')} /><ComplianceTimeline timeline={command.timeline} returns={data.returns} onOpen={setSelectedReturn} /></section><PolicyDistribution data={command.policyDistribution} /></> : null}
    {tab === 'liabilities' ? <LiabilitiesView data={data} transactions={filtered} filter={liabilityFilter} onFilter={setLiabilityFilter} onPost={setPostingMode} /> : null}
    {tab === 'returns' ? <ReturnsView returns={data.returns} onOpen={setSelectedReturn} prepare={prepare} /> : null}
    {tab === 'policies' ? <PoliciesView policies={policies.data || []} onBuild={() => setPolicyBuilder(true)} /> : null}
    {selectedReturn ? <ReturnDrawer item={selectedReturn} onClose={() => setSelectedReturn(null)} onRefresh={refresh} /> : null}
    {postingMode ? <PostingDrawer mode={postingMode} policies={policies.data || []} onClose={() => setPostingMode(null)} onRefresh={refresh} /> : null}
    {policyBuilder ? <PolicyBuilder onClose={() => setPolicyBuilder(false)} onRefresh={refresh} /> : null}
  </main>
}

function LiabilityPicture({ data, onFilter, onOpen }: { data: any; onFilter: (filter: 'all' | 'TDS' | 'TCS') => void; onOpen: () => void }) { const total = Math.max(1, Number(data.liabilities.totalPaise || 0)); const tds = Number(data.liabilities.tdsPaise || 0); const tcs = Number(data.liabilities.tcsPaise || 0); return <CommandPanel eyebrow="Liability picture" title="What is recorded this period" icon="liability"><button type="button" onClick={onOpen} className="w-full text-left"><p className="font-display text-3xl font-semibold tracking-[-.04em] text-[#17353c]">{money(data.liabilities.totalPaise)}</p><p className="mt-1 text-xs text-[#657681]">Posted liabilities—not a payment or filing confirmation.</p><div className="mt-6 flex h-4 overflow-hidden rounded-full bg-[#eef1f3]" aria-label={`TDS ${money(tds)} and TCS ${money(tcs)}`}><span className="bg-[#6b4df5]" style={{ width: `${(tds / total) * 100}%` }} /><span className="bg-[#2c9188]" style={{ width: `${(tcs / total) * 100}%` }} /></div></button><div className="mt-4 grid gap-2 sm:grid-cols-2"><SegmentButton color="violet" label="Income-tax TDS" value={money(tds)} percent={tds / total} onClick={() => { onFilter('TDS'); onOpen() }} /><SegmentButton color="teal" label="GST / income-tax TCS" value={money(tcs)} percent={tcs / total} onClick={() => { onFilter('TCS'); onOpen() }} /></div></CommandPanel> }
function ComplianceTimeline({ timeline, returns, onOpen }: { timeline: any[]; returns: ReturnRecord[]; onOpen: (item: ReturnRecord | null) => void }) { return <CommandPanel eyebrow="Compliance timeline" title="What comes next" icon="calendar"><div className="space-y-1">{timeline.length ? timeline.slice(0, 5).map((item) => <button type="button" key={item.id} onClick={() => onOpen(returns.find((record) => record.id === item.id) || null)} className="group flex w-full gap-3 rounded-2xl p-3 text-left transition hover:bg-[#f6f8fb]"><div className="flex w-11 shrink-0 flex-col items-center"><StatusDot tone={timelineTone(item.dueState)} /><span className="mt-1 whitespace-nowrap text-[10px] font-bold text-[#657681]">{String(item.date).slice(5)}</span></div><div className="min-w-0 flex-1 border-l border-[#dfe6e8] pl-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-extrabold text-[#17353c]">{item.label}</p><p className="mt-0.5 text-xs text-[#657681]">{returnStateCopy(item.state, item.dueState)}</p></div><strong className="shrink-0 text-sm tabular-nums text-[#17353c]">{money(item.amountPaise)}</strong></div></div><ChevronRight className="mt-1 h-4 w-4 text-[#a3afb5] group-hover:text-[#5d42e8]" /></button>) : <SmartEmpty type="calendar" title="Nothing is due yet" detail="Prepare a statutory return only when the period and source records are ready." />}</div></CommandPanel> }
function PolicyDistribution({ data }: { data: any[] }) { return <CommandPanel eyebrow="Source of liability" title="Which policies created the balance" icon="policy"><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{data.length ? data.map((item) => <article key={item.policyKey} className="rounded-2xl border border-[#273d4a]/8 bg-[#fbfcfc] p-4"><div className="flex items-start justify-between gap-3"><FinanceMark type="policy" /><span className="rounded-full bg-[#edf7f3] px-2 py-1 text-[10px] font-extrabold text-[#337065]">{item.count} source{item.count === 1 ? '' : 's'}</span></div><p className="mt-4 text-sm font-extrabold text-[#17353c]">{item.label || policyName(item.policyKey)}</p><p className="mt-1 text-xl font-display font-semibold tracking-[-.025em] text-[#17353c]">{money(item.amountPaise)}</p><details className="mt-3"><summary className="cursor-pointer text-xs font-bold text-[#64747e]">Technical details</summary><p className="mt-2 break-all text-[11px] leading-5 text-[#74848a]">Policy key: {item.policyKey}</p></details></article>) : <div className="md:col-span-2 xl:col-span-3"><SmartEmpty type="policy" title="No policy activity in this period" detail="Posted TDS/TCS entries will appear here with the policy version that created them." /></div>}</div></CommandPanel> }
function LiabilitiesView({ data, transactions, filter, onFilter, onPost }: { data: any; transactions: any[]; filter: 'all' | 'TDS' | 'TCS'; onFilter: (filter: 'all' | 'TDS' | 'TCS') => void; onPost: (mode: 'tds' | 'gst-tcs' | 'income-tcs') => void }) { return <section className="space-y-5"><section className="grid gap-4 lg:grid-cols-[1.2fr_.8fr]"><LiabilityPicture data={data} onFilter={onFilter} onOpen={() => undefined} /><CommandPanel eyebrow="Actions" title="Add with a calculation preview" icon="calculator"><p className="text-sm leading-6 text-[#64747e]">The preview explains the source value, policy and resulting liability before anything is posted. Posted records stay linked to their source reference.</p><div className="mt-5 flex flex-wrap gap-2"><ActionButton label="Post TDS" onClick={() => onPost('tds')} /><ActionButton label="Post GST TCS" onClick={() => onPost('gst-tcs')} /><ActionButton label="Post income-tax TCS" onClick={() => onPost('income-tcs')} /></div></CommandPanel></section><CommandPanel eyebrow="Source transactions" title="Trace every amount back to its source" icon="evidence"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div className="flex gap-1 rounded-xl bg-[#f0f3f4] p-1">{([['all', 'All'], ['TDS', 'TDS'], ['TCS', 'TCS']] as const).map(([value, label]) => <button key={value} type="button" onClick={() => onFilter(value)} className={`rounded-lg px-3 py-1.5 text-xs font-bold transition ${filter === value ? 'bg-white text-[#17353c] shadow-sm' : 'text-[#64747e]'}`}>{label}</button>)}</div><p className="text-xs text-[#64747e]">{transactions.length} record{transactions.length === 1 ? '' : 's'} shown</p></div><div className="overflow-x-auto rounded-2xl border border-[#dfe6e8]"><table className="w-full min-w-[720px] text-left"><thead className="bg-[#f7f9fa] text-[10px] font-extrabold uppercase tracking-[.12em] text-[#6e7f88]"><tr><th className="px-4 py-3">Date</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Policy</th><th className="px-4 py-3">Source reference</th><th className="px-4 py-3 text-right">Liability</th><th className="px-4 py-3">Record</th></tr></thead><tbody>{transactions.length ? transactions.map((item) => <tr key={item.id} className="border-t border-[#e8edef] text-sm"><td className="px-4 py-3 text-[#64747e]">{item.postingDate}</td><td className="px-4 py-3"><span className={`rounded-full px-2.5 py-1 text-[10px] font-extrabold ${item.entity === 'finance_tds_transaction' ? 'bg-[#f0edff] text-[#5b43d3]' : 'bg-[#e9f7f4] text-[#287369]'}`}>{item.entity === 'finance_tds_transaction' ? 'TDS' : 'TCS'}</span></td><td className="px-4 py-3"><p className="font-bold text-[#17353c]">{policyName(item.calculation?.policyKey || item.policyVersion || '')}</p><p className="mt-0.5 text-[11px] text-[#74848a]">{item.calculation?.policyVersion || item.policyVersion}</p></td><td className="px-4 py-3 font-mono text-xs text-[#53666f]">{item.sourceReference}</td><td className="px-4 py-3 text-right font-bold tabular-nums text-[#17353c]">{money(item.amountPaise)}</td><td className="px-4 py-3"><span className="inline-flex items-center gap-1 text-xs font-bold text-[#287369]"><CheckCircle2 className="h-3.5 w-3.5" /> Posted</span></td></tr>) : <tr><td colSpan={6} className="p-6"><SmartEmpty type="liability" title="No matching posted liabilities" detail="Use a real source reference to create a controlled TDS or TCS record." /></td></tr>}</tbody></table></div></CommandPanel></section> }
function ReturnsView({ returns, onOpen, prepare }: { returns: ReturnRecord[]; onOpen: (item: ReturnRecord | null) => void; prepare: any }) { const [form, setForm] = useState({ returnType: 'TDS_140', periodStart: monthStart, periodEnd: today }); return <section className="space-y-5"><CommandPanel eyebrow="Compliance calendar" title="Returns, evidence and next action" icon="return"><div className="grid gap-3 lg:grid-cols-[1fr_1fr_1fr_auto]"><Select label="Return" value={form.returnType} onChange={(returnType) => setForm({ ...form, returnType })} options={[['TDS_140', 'Form 140 · resident non-salary TDS'], ['TDS_138', 'Form 138 · salary TDS'], ['TCS_143', 'Form 143 · income-tax TCS'], ['GSTR_8', 'GSTR-8 · GST ECO TCS']]} /><Field label="Period start" type="date" value={form.periodStart} onChange={(periodStart) => setForm({ ...form, periodStart })} /><Field label="Period end" type="date" value={form.periodEnd} onChange={(periodEnd) => setForm({ ...form, periodEnd })} /><button type="button" disabled={prepare.isPending} onClick={() => prepare.mutate(form)} className="mt-5 inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#203647] px-4 text-sm font-bold text-white transition hover:bg-[#142b3c] disabled:opacity-50"><CalendarClock className="h-4 w-4" />{prepare.isPending ? 'Preparing…' : 'Prepare return'}</button></div>{prepare.error ? <ErrorNotice error={prepare.error} /> : null}</CommandPanel><section className="grid gap-3 lg:grid-cols-2">{returns.length ? returns.map((item) => <button key={item.id} type="button" onClick={() => onOpen(item)} className="group rounded-[22px] border border-[#273d4a]/10 bg-white p-5 text-left shadow-[0_8px_28px_rgba(37,48,43,.04)] transition hover:-translate-y-0.5 hover:border-[#6b4df5]/30 hover:shadow-[0_14px_34px_rgba(37,48,43,.08)]"><div className="flex items-start justify-between gap-3"><div className="flex items-center gap-3"><FinanceMark type="return" /><div><p className="text-sm font-extrabold text-[#17353c]">{returnForm(item.returnType)}</p><p className="mt-0.5 text-xs text-[#657681]">{returnName(item.returnType)}</p></div></div><ReturnBadge state={item.state} dueDate={item.dueDate} /></div><div className="mt-5 grid grid-cols-3 gap-2 border-y border-[#e8edef] py-4"><MiniMetric label="Sources" value={String(item.transactionCount)} /><MiniMetric label="Liability" value={money(item.amountPaise)} /><MiniMetric label="Due" value={item.dueDate.slice(5)} /></div><div className="mt-4 flex items-center justify-between text-xs"><span className="text-[#64747e]">{item.evidence ? 'Evidence recorded' : 'Evidence not yet recorded'}</span><span className="inline-flex items-center gap-1 font-extrabold text-[#5d42e8]">Open workspace <ChevronRight className="h-3.5 w-3.5 transition group-hover:translate-x-0.5" /></span></div></button>) : <div className="lg:col-span-2"><SmartEmpty type="return" title="No prepared returns" detail="Select the period above only when its source transactions are ready to be captured in a return workspace." /></div>}</section></section> }
function PoliciesView({ policies, onBuild }: { policies: any[]; onBuild: () => void }) { return <section className="space-y-5"><CommandPanel eyebrow="Policy library" title="Rules stay versioned; people see plain language" icon="policy"><div className="flex flex-col gap-4 rounded-2xl border border-[#dfe6e8] bg-[#f8fafb] p-4 md:flex-row md:items-center md:justify-between"><div><p className="font-bold text-[#17353c]">Income-tax TCS policy builder</p><p className="mt-1 max-w-2xl text-sm leading-6 text-[#64747e]">Use this guided workspace for accountant-configured income-tax TCS. TDS and GST ECO TCS retain their controlled statutory-policy architecture and are not editable as a casual form.</p></div><button type="button" onClick={onBuild} className="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl bg-[#6b4df5] px-4 py-2.5 text-sm font-extrabold text-white transition hover:bg-[#5940db]"><Plus className="h-4 w-4" /> Create policy</button></div></CommandPanel><section className="grid gap-3 lg:grid-cols-2">{policies.length ? policies.map((policy) => <article key={policy.id} className="rounded-[22px] border border-[#273d4a]/10 bg-white p-5 shadow-[0_8px_28px_rgba(37,48,43,.04)]"><div className="flex items-start justify-between gap-3"><div className="flex items-center gap-3"><FinanceMark type="policy" /><div><p className="font-bold text-[#17353c]">Income-tax TCS</p><p className="mt-0.5 text-xs text-[#657681]">{Number(policy.rateBps || 0) / 100}% · {policy.effectiveFrom}{policy.effectiveUntil ? ` → ${policy.effectiveUntil}` : ' onward'}</p></div></div><PolicyBadge status={policy.status} /></div><p className="mt-4 text-sm leading-6 text-[#53666f]">{policy.calculationBasis}</p><details className="mt-4 rounded-xl bg-[#f7f9fa] p-3"><summary className="cursor-pointer text-xs font-bold text-[#53666f]">Advanced policy details</summary><dl className="mt-3 grid gap-2 text-xs text-[#657681]"><div><dt className="font-bold text-[#42565f]">Version</dt><dd>{policy.version}</dd></div><div><dt className="font-bold text-[#42565f]">Policy key</dt><dd className="break-all font-mono text-[11px]">{policy.policyKey}</dd></div><div><dt className="font-bold text-[#42565f]">Source note</dt><dd>{policy.sourceNote || 'No note supplied'}</dd></div></dl></details></article>) : <div className="lg:col-span-2"><SmartEmpty type="policy" title="No income-tax TCS policy configured" detail="Create a reviewable, effective-dated policy before an income-tax TCS liability can be calculated." action="Create policy" onAction={onBuild} /></div>}</section></section> }

function ReturnDrawer({ item, onClose, onRefresh }: { item: ReturnRecord; onClose: () => void; onRefresh: () => void }) {
  const [draft, setDraft] = useState({ state: item.state, evidence: item.evidence || '', acknowledgement: item.acknowledgement || '' })
  const update = useMutation({ mutationFn: () => apiPost(`/finance/statutory-returns/${item.id}/status`, draft), onSuccess: () => { onRefresh(); onClose() } })
  const stages = [
    { label: 'Transactions', done: true },
    { label: 'Liability', done: true },
    { label: 'Evidence check', done: Boolean(item.evidence) },
    { label: 'Return prepared', done: true },
    { label: 'Submitted', done: ['Submitted', 'Acknowledged', 'Accepted'].includes(item.state) },
    { label: 'Acknowledged', done: ['Acknowledged', 'Accepted'].includes(item.state) }
  ]
  const completed = stages.filter((stage) => stage.done).length
  return <Drawer title={returnForm(item.returnType)} subtitle={`${item.periodStart} → ${item.periodEnd}`} onClose={onClose}><div className="space-y-6"><div className="rounded-2xl border border-[#dfe6e8] bg-[#f7f9fa] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[.16em] text-[#657681]">Current state</p><p className="mt-2 text-lg font-display font-semibold text-[#17353c]">{returnStateCopy(item.state, '')}</p></div><ReturnBadge state={item.state} dueDate={item.dueDate} /></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-[#dde4e7]"><span className="block h-full rounded-full bg-[#6b4df5] transition-all duration-500" style={{ width: `${(completed / stages.length) * 100}%` }} /></div><div className="mt-4 grid grid-cols-2 gap-x-3 gap-y-2">{stages.map((stage) => <div key={stage.label} className="flex items-center gap-2 text-xs"><CheckCircle2 className={`h-3.5 w-3.5 ${stage.done ? 'text-[#26826d]' : 'text-[#a7b3b8]'}`} /><span className={stage.done ? 'font-bold text-[#43565e]' : 'text-[#78878e]'}>{stage.label}</span></div>)}</div></div><section><SectionLabel>Reconciled snapshot</SectionLabel><div className="mt-3 grid grid-cols-3 gap-2"><MiniMetric label="Sources" value={String(item.transactionCount)} /><MiniMetric label="Liability" value={money(item.amountPaise)} /><MiniMetric label="Due" value={item.dueDate} /></div></section><section><SectionLabel>Evidence</SectionLabel><div className="mt-3 rounded-2xl border border-[#dfe6e8] p-4"><p className="text-sm font-bold text-[#17353c]">Record portal evidence, not a fabricated filing.</p><p className="mt-1 text-xs leading-5 text-[#657681]">Use an actual challan, portal receipt or ARN reference. This local installation does not claim a government upload.</p><div className="mt-4 space-y-3"><Field label="Portal reference / challan / ARN" value={draft.evidence} onChange={(evidence) => setDraft({ ...draft, evidence })} placeholder="Enter actual reference" /><Field label="Acknowledgement number" value={draft.acknowledgement} onChange={(acknowledgement) => setDraft({ ...draft, acknowledgement })} placeholder="Required only for Accepted" /><Select label="Return state" value={draft.state} onChange={(state) => setDraft({ ...draft, state })} options={[['Prepared', 'Prepared'], ['Validated', 'Validated'], ['Exported', 'Exported'], ['Submitted', 'Submitted'], ['Acknowledged', 'Acknowledged'], ['Accepted', 'Accepted'], ['CorrectionRequired', 'Correction required']]} /></div><button type="button" disabled={update.isPending} onClick={() => update.mutate()} className="mt-4 inline-flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-[#203647] text-sm font-extrabold text-white transition hover:bg-[#142b3c] disabled:opacity-50"><FileCheck2 className="h-4 w-4" />{update.isPending ? 'Saving…' : 'Save evidence state'}</button>{update.error ? <ErrorNotice error={update.error} /> : null}</div></section><section className="rounded-2xl border border-[#e8ddbe] bg-[#fffaf0] p-4"><div className="flex gap-3"><ShieldCheck className="h-5 w-5 shrink-0 text-[#946d1f]" /><div><p className="text-sm font-bold text-[#73561b]">Audit-safe controls</p><p className="mt-1 text-xs leading-5 text-[#806a3c]">Return states require evidence before submission and an acknowledgement before acceptance. Source transactions and their policy snapshots remain unchanged.</p></div></div></section></div></Drawer>
}

function PostingDrawer({ mode, policies, onClose, onRefresh }: { mode: 'tds' | 'gst-tcs' | 'income-tcs'; policies: any[]; onClose: () => void; onRefresh: () => void }) {
  const [tds, setTds] = useState({ sourceReference: '', postingDate: today, category: 'CONTRACTOR', payeeName: '', payeeType: 'OTHER', base: '', aggregate: '', panStatus: 'UNKNOWN', buyerTurnover: '', participantExemptionEligible: false })
  const [tcs, setTcs] = useState({ sourceReference: '', postingDate: today, taxableSupply: '', returnedSupply: '', intraState: true, policyKey: '' })
  const [preview, setPreview] = useState<any>(null)
  const approved = policies.filter((policy: any) => policy.status === 'APPROVED')
  const calculate = useMutation({ mutationFn: () => mode === 'tds' ? apiPost('/finance/tds/calculate', { sourceReference: tds.sourceReference || 'preview', postingDate: tds.postingDate, category: tds.category, payeeName: tds.payeeName || 'Preview payee', payeeType: tds.payeeType, basePaise: moneyPaise(tds.base), aggregatePaise: moneyPaise(tds.aggregate || tds.base), panStatus: tds.panStatus, buyerTurnoverPaise: moneyPaise(tds.buyerTurnover), participantExemptionEligible: tds.participantExemptionEligible }) : apiPost('/finance/tcs/calculate', mode === 'gst-tcs' ? { category: 'GST_ECO_TCS', postingDate: tcs.postingDate, taxableSupplyPaise: moneyPaise(tcs.taxableSupply), returnedSupplyPaise: moneyPaise(tcs.returnedSupply), intraState: tcs.intraState } : { category: 'INCOME_TAX_TCS', postingDate: tcs.postingDate, taxableSupplyPaise: moneyPaise(tcs.taxableSupply), policyKey: tcs.policyKey }), onSuccess: setPreview })
  const post = useMutation({ mutationFn: () => mode === 'tds' ? apiPost('/finance/tds/transactions', { sourceReference: tds.sourceReference, postingDate: tds.postingDate, category: tds.category, payeeName: tds.payeeName, payeeType: tds.payeeType, basePaise: moneyPaise(tds.base), aggregatePaise: moneyPaise(tds.aggregate || tds.base), panStatus: tds.panStatus, buyerTurnoverPaise: moneyPaise(tds.buyerTurnover), participantExemptionEligible: tds.participantExemptionEligible }) : apiPost('/finance/tcs/transactions', mode === 'gst-tcs' ? { sourceReference: tcs.sourceReference, postingDate: tcs.postingDate, category: 'GST_ECO_TCS', taxableSupplyPaise: moneyPaise(tcs.taxableSupply), returnedSupplyPaise: moneyPaise(tcs.returnedSupply), intraState: tcs.intraState } : { sourceReference: tcs.sourceReference, postingDate: tcs.postingDate, category: 'INCOME_TAX_TCS', taxableSupplyPaise: moneyPaise(tcs.taxableSupply), policyKey: tcs.policyKey }), onSuccess: () => { onRefresh(); onClose() } })
  const meta = mode === 'tds' ? { title: 'Post TDS liability', subtitle: 'A controlled withholding record', sourceLabel: 'Vendor bill / contract reference' } : mode === 'gst-tcs' ? { title: 'Post GST ECO TCS', subtitle: 'Net taxable supply after returns', sourceLabel: 'Marketplace source reference' } : { title: 'Post income-tax TCS', subtitle: 'Only from an approved, effective policy', sourceLabel: 'Marketplace source reference' }
  return <Drawer title={meta.title} subtitle={meta.subtitle} onClose={onClose}><div className="space-y-5"><div className="rounded-2xl border border-[#dfe6e8] bg-[#f7f9fa] p-4"><div className="flex items-center gap-3"><FinanceMark type="calculator" /><div><p className="text-sm font-bold text-[#17353c]">Calculation preview first</p><p className="mt-1 text-xs leading-5 text-[#657681]">The preview is explainable. Posting remains idempotent against the source reference.</p></div></div></div>{mode === 'tds' ? <div className="grid gap-3"><Field label="Source reference" required value={tds.sourceReference} onChange={(sourceReference) => { setTds({ ...tds, sourceReference }); setPreview(null) }} placeholder={meta.sourceLabel} /><Field label="Payee name" value={tds.payeeName} onChange={(payeeName) => { setTds({ ...tds, payeeName }); setPreview(null) }} /><div className="grid gap-3 sm:grid-cols-2"><Field label="Posting date" type="date" value={tds.postingDate} onChange={(postingDate) => { setTds({ ...tds, postingDate }); setPreview(null) }} /><Select label="Covered payment" value={tds.category} onChange={(category) => { setTds({ ...tds, category }); setPreview(null) }} options={[['CONTRACTOR', 'Contractor'], ['COMMISSION', 'Commission'], ['RENT_EQUIPMENT', 'Equipment rent'], ['RENT_PROPERTY', 'Property rent'], ['PROFESSIONAL', 'Professional services'], ['TECHNICAL', 'Technical services'], ['GOODS_PURCHASE', 'Purchase of goods'], ['ECOMMERCE', 'E-commerce participant']]} /></div><div className="grid gap-3 sm:grid-cols-2"><MoneyField label="Current eligible value" value={tds.base} onChange={(base) => { setTds({ ...tds, base }); setPreview(null) }} /><MoneyField label="Annual / period aggregate" value={tds.aggregate} onChange={(aggregate) => { setTds({ ...tds, aggregate }); setPreview(null) }} /></div><div className="grid gap-3 sm:grid-cols-2"><Select label="Payee type" value={tds.payeeType} onChange={(payeeType) => { setTds({ ...tds, payeeType }); setPreview(null) }} options={[['OTHER', 'Other resident payee'], ['INDIVIDUAL_HUF', 'Individual / HUF']]} /><Select label="PAN evidence" value={tds.panStatus} onChange={(panStatus) => { setTds({ ...tds, panStatus }); setPreview(null) }} options={[['UNKNOWN', 'Not verified'], ['VALID', 'Valid'], ['MISSING', 'Missing'], ['INVALID', 'Invalid'], ['INOPERATIVE', 'Inoperative']]} /></div>{tds.category === 'GOODS_PURCHASE' ? <MoneyField label="Buyer preceding-year turnover" value={tds.buyerTurnover} onChange={(buyerTurnover) => { setTds({ ...tds, buyerTurnover }); setPreview(null) }} /> : null}{tds.category === 'ECOMMERCE' ? <label className="flex items-center gap-2 rounded-xl bg-[#f7f9fa] p-3 text-xs font-bold text-[#53666f]"><input type="checkbox" checked={tds.participantExemptionEligible} onChange={(event) => { setTds({ ...tds, participantExemptionEligible: event.target.checked }); setPreview(null) }} className="h-4 w-4 accent-[#5d42e8]" />Verified participant exception applies</label> : null}</div> : <div className="grid gap-3"><Field label="Source reference" required value={tcs.sourceReference} onChange={(sourceReference) => { setTcs({ ...tcs, sourceReference }); setPreview(null) }} placeholder={meta.sourceLabel} /><Field label="Posting date" type="date" value={tcs.postingDate} onChange={(postingDate) => { setTcs({ ...tcs, postingDate }); setPreview(null) }} /><MoneyField label={mode === 'gst-tcs' ? 'Taxable supply value' : 'Covered taxable value'} value={tcs.taxableSupply} onChange={(taxableSupply) => { setTcs({ ...tcs, taxableSupply }); setPreview(null) }} />{mode === 'gst-tcs' ? <><MoneyField label="Returned supply value" value={tcs.returnedSupply} onChange={(returnedSupply) => { setTcs({ ...tcs, returnedSupply }); setPreview(null) }} /><label className="flex items-center gap-2 rounded-xl bg-[#f7f9fa] p-3 text-xs font-bold text-[#53666f]"><input type="checkbox" checked={tcs.intraState} onChange={(event) => { setTcs({ ...tcs, intraState: event.target.checked }); setPreview(null) }} className="h-4 w-4 accent-[#2a8e84]" />Intra-state (CGST + SGST allocation)</label></> : <Select label="Approved policy" value={tcs.policyKey} onChange={(policyKey) => { setTcs({ ...tcs, policyKey }); setPreview(null) }} options={approved.length ? approved.map((policy: any) => [policy.policyKey, `${Number(policy.rateBps) / 100}% · ${policy.policyKey}`]) : [['', 'No approved policy available']]} />}</div>}<button type="button" disabled={calculate.isPending} onClick={() => calculate.mutate()} className="inline-flex h-10 w-full items-center justify-center gap-2 rounded-xl border border-[#6b4df5]/30 bg-[#f5f2ff] text-sm font-extrabold text-[#5540cd] transition hover:bg-[#eeeaff] disabled:opacity-50"><Calculator className="h-4 w-4" />{calculate.isPending ? 'Calculating…' : 'Show calculation preview'}</button>{calculate.error ? <ErrorNotice error={calculate.error} /> : null}{preview ? <CalculationPreview preview={preview} /> : null}<button type="button" disabled={!preview || post.isPending || !((mode === 'tds' ? tds.sourceReference : tcs.sourceReference).trim())} onClick={() => post.mutate()} className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-[#203647] text-sm font-extrabold text-white transition hover:bg-[#142b3c] disabled:cursor-not-allowed disabled:opacity-40"><ShieldCheck className="h-4 w-4" />{post.isPending ? 'Posting…' : preview ? `Post ${money(preview.amountPaise)} liability` : 'Preview before posting'}</button>{post.error ? <ErrorNotice error={post.error} /> : null}</div></Drawer>
}

function PolicyBuilder({ onClose, onRefresh }: { onClose: () => void; onRefresh: () => void }) {
  const [step, setStep] = useState(1); const [policy, setPolicy] = useState({ policyKey: 'INCOME_TAX_TCS_MARKETPLACE', ratePercent: '', effectiveFrom: '2026-04-01', effectiveUntil: '', calculationBasis: 'Covered marketplace participant gross sales/services basis.', sourceNote: '', status: 'DRAFT', version: 'TCS-2026.1' })
  const save = useMutation({ mutationFn: () => apiPut('/finance/tcs/policies', { ...policy, rateBps: Math.round(Number(policy.ratePercent || 0) * 100), effectiveUntil: policy.effectiveUntil || undefined }), onSuccess: () => { onRefresh(); onClose() } })
  return <Drawer title="Create income-tax TCS policy" subtitle="Guided, effective-dated configuration" onClose={onClose}><div className="space-y-6"><div className="flex items-center gap-1">{['Payment type', 'Applicability', 'Rate & period', 'Review'].map((label, index) => <div key={label} className="flex min-w-0 flex-1 items-center gap-1"><button type="button" onClick={() => setStep(index + 1)} className={`grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-extrabold ${step >= index + 1 ? 'bg-[#6b4df5] text-white' : 'bg-[#e9edef] text-[#657681]'}`}>{index + 1}</button>{index < 3 ? <span className={`h-0.5 flex-1 ${step > index + 1 ? 'bg-[#6b4df5]' : 'bg-[#dce3e6]'}`} /> : null}</div>)}</div>{step === 1 ? <section><SectionLabel>What type of policy is this?</SectionLabel><div className="mt-3 grid gap-2"><Choice selected label="Income-tax TCS" detail="Accountant-configured withholding policy for an eligible marketplace scenario." /><Choice label="GST ECO TCS" detail="Controlled statutory calculation, supplied by the regulated GST workflow." disabled /></div></section> : null}{step === 2 ? <section className="space-y-3"><SectionLabel>Who and what does it apply to?</SectionLabel><p className="text-sm leading-6 text-[#64747e]">Describe the covered participant or transaction in the calculation basis. The platform does not infer legal applicability from a label.</p><label className="block text-xs font-bold text-[#53666f]">Calculation basis<textarea value={policy.calculationBasis} onChange={(event) => setPolicy({ ...policy, calculationBasis: event.target.value })} className="mt-1 min-h-28 w-full rounded-xl border border-[#d6dfe3] bg-white p-3 text-sm text-[#17353c] outline-none focus:ring-2 focus:ring-[#6b4df5]/40" /></label></section> : null}{step === 3 ? <section className="grid gap-3"><SectionLabel>Rate and effective dates</SectionLabel><Field label="Policy key" value={policy.policyKey} onChange={(policyKey) => setPolicy({ ...policy, policyKey })} /><MoneyField label="Rate (%)" value={policy.ratePercent} onChange={(ratePercent) => setPolicy({ ...policy, ratePercent })} /><div className="grid gap-3 sm:grid-cols-2"><Field label="Effective from" type="date" value={policy.effectiveFrom} onChange={(effectiveFrom) => setPolicy({ ...policy, effectiveFrom })} /><Field label="Effective until" type="date" value={policy.effectiveUntil} onChange={(effectiveUntil) => setPolicy({ ...policy, effectiveUntil })} /></div><Field label="Version" value={policy.version} onChange={(version) => setPolicy({ ...policy, version })} /></section> : null}{step === 4 ? <section className="space-y-3"><SectionLabel>Review before creating</SectionLabel><div className="rounded-2xl border border-[#dfe6e8] bg-[#f7f9fa] p-4 text-sm"><dl className="space-y-3"><Row label="Policy" value={policy.policyKey} /><Row label="Rate" value={`${policy.ratePercent || '—'}%`} /><Row label="Effective" value={`${policy.effectiveFrom} → ${policy.effectiveUntil || 'open'}`} /><Row label="Basis" value={policy.calculationBasis} /></dl></div><label className="block text-xs font-bold text-[#53666f]">Accountant source note<textarea value={policy.sourceNote} onChange={(event) => setPolicy({ ...policy, sourceNote: event.target.value })} placeholder="Record the approved basis; do not invent a statutory rule." className="mt-1 min-h-20 w-full rounded-xl border border-[#d6dfe3] bg-white p-3 text-sm text-[#17353c] outline-none focus:ring-2 focus:ring-[#6b4df5]/40" /></label><Select label="Recorded lifecycle" value={policy.status} onChange={(status) => setPolicy({ ...policy, status })} options={[['DRAFT', 'Draft'], ['APPROVED', 'Approved'], ['RETIRED', 'Retired']]} /></section> : null}<div className="flex items-center justify-between gap-3 border-t border-[#e2e8ea] pt-4"><button type="button" disabled={step === 1} onClick={() => setStep(step - 1)} className="text-sm font-bold text-[#64747e] disabled:opacity-30">Back</button>{step < 4 ? <button type="button" onClick={() => setStep(step + 1)} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#6b4df5] px-4 text-sm font-extrabold text-white">Continue <ChevronRight className="h-4 w-4" /></button> : <button type="button" disabled={save.isPending || !policy.policyKey || !policy.ratePercent || !policy.effectiveFrom || !policy.calculationBasis} onClick={() => save.mutate()} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#203647] px-4 text-sm font-extrabold text-white disabled:opacity-40"><ShieldCheck className="h-4 w-4" />{save.isPending ? 'Saving…' : 'Create policy'}</button>}</div>{save.error ? <ErrorNotice error={save.error} /> : null}</div></Drawer>
}

function CalculationPreview({ preview }: { preview: any }) { const rate = preview.rateBps !== undefined ? `${Number(preview.rateBps) / 100}%` : preview.ratePercent !== undefined ? `${preview.ratePercent}%` : 'Configured rate'; const basis = preview.netTaxableSupplyPaise ?? preview.taxableSupplyPaise ?? preview.basePaise ?? preview.calculationBasisPaise; return <section className="rounded-2xl border border-[#cfc6ff] bg-[#f7f5ff] p-4"><div className="flex items-center gap-2"><Calculator className="h-4 w-4 text-[#5d42e8]" /><p className="text-sm font-extrabold text-[#3e2da6]">Calculation preview</p></div><div className="mt-4 space-y-2 text-sm"><Row label="Eligible transaction value" value={basis !== undefined ? money(basis) : 'Configured source basis'} /><Row label="Applied rate" value={rate} /><div className="border-t border-[#ddd7ff] pt-2"><Row label="Resulting liability" value={money(preview.amountPaise)} strong /></div></div><details className="mt-4"><summary className="cursor-pointer text-xs font-bold text-[#5d42e8]">How was this calculated?</summary><p className="mt-2 text-xs leading-5 text-[#62598d]">The server applies the effective policy, threshold, category and evidence inputs. Posting recalculates independently and keeps the source reference idempotent.</p></details>{preview.status && preview.status !== 'APPLICABLE' ? <p className="mt-3 rounded-xl bg-white/70 p-2 text-xs font-bold text-[#62598d]">Result: {String(preview.status).replace(/_/g, ' ')}</p> : null}</section> }
function useStatutoryDrawerFocus(onClose: () => void) {
  const drawerRef = useRef<HTMLElement | null>(null)
  const closeRef = useRef<HTMLButtonElement | null>(null)
  const closeHandler = useRef(onClose)
  const previousFocusRef = useRef<HTMLElement | null>(null)
  closeHandler.current = onClose

  const restoreFocus = () => {
    const previous = previousFocusRef.current
    if (!previous?.isConnected) return
    previous.focus()
    window.requestAnimationFrame(() => {
      if (previous.isConnected) previous.focus()
    })
  }

  useEffect(() => {
    previousFocusRef.current = document.activeElement instanceof HTMLElement ? document.activeElement : null
    const frame = window.requestAnimationFrame(() => (closeRef.current || drawerRef.current)?.focus())
    const onEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        restoreFocus()
        closeHandler.current()
      }
    }
    document.addEventListener('keydown', onEscape)
    return () => {
      window.cancelAnimationFrame(frame)
      document.removeEventListener('keydown', onEscape)
      restoreFocus()
    }
  }, [])

  const onKeyDown = (event: ReactKeyboardEvent<HTMLElement>) => {
    if (event.key !== 'Tab') return
    const focusable = Array.from(drawerRef.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [href], [tabindex]:not([tabindex="-1"])') || [])
    if (!focusable.length) {
      event.preventDefault()
      drawerRef.current?.focus()
      return
    }
    const first = focusable[0]
    const last = focusable[focusable.length - 1]
    if (!drawerRef.current?.contains(document.activeElement)) {
      event.preventDefault()
      ;(event.shiftKey ? last : first).focus()
    } else if (event.shiftKey && document.activeElement === first) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }

  return { drawerRef, closeRef, onKeyDown, restoreFocus }
}

function Drawer({ title, subtitle, children, onClose }: { title: string; subtitle: string; children: ReactNode; onClose: () => void }) { const focus = useStatutoryDrawerFocus(onClose); return <div className="fixed inset-0 z-50 flex justify-end bg-[#0e1e2b]/45 p-0 backdrop-blur-[1px]" role="dialog" aria-modal="true" aria-label={title}><button type="button" aria-label="Close panel backdrop" onClick={onClose} className="absolute inset-0 cursor-default" /><aside ref={focus.drawerRef} onKeyDown={focus.onKeyDown} tabIndex={-1} className="animate-in slide-in-from-right flex h-full w-full max-w-xl flex-col bg-[#fffefd] shadow-[-18px_0_50px_rgba(13,31,43,.22)]"><div className="flex items-start justify-between border-b border-[#e3e9eb] px-5 py-5"><div><p className="text-[10px] font-extrabold uppercase tracking-[.16em] text-[#6b4df5]">Statutory workspace</p><h2 className="mt-1 font-display text-2xl font-semibold tracking-[-.035em] text-[#17353c]">{title}</h2><p className="mt-1 text-sm text-[#64747e]">{subtitle}</p></div><button ref={focus.closeRef} type="button" aria-label="Close panel" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl border border-[#dce4e6] text-[#52656e] transition hover:bg-[#f4f6f7]"><X className="h-4 w-4" /></button></div><div className="flex-1 overflow-y-auto px-5 py-5">{children}</div></aside></div> }
function CommandPanel({ eyebrow, title, icon, children }: { eyebrow: string; title: string; icon: IconType; children: ReactNode }) { return <section className="rounded-[24px] border border-[#273d4a]/10 bg-white p-5 shadow-[0_10px_30px_rgba(37,48,43,.045)] md:p-6"><div className="flex items-center gap-3"><FinanceMark type={icon} /><div><p className="text-[10px] font-extrabold uppercase tracking-[.16em] text-[#597f85]">{eyebrow}</p><h2 className="mt-0.5 font-display text-xl font-semibold tracking-[-.03em] text-[#17353c]">{title}</h2></div></div><div className="mt-5">{children}</div></section> }
function FinanceMark({ type, inverse = false }: { type: IconType; inverse?: boolean }) { const Icon = type === 'liability' ? ReceiptIndianRupee : type === 'calendar' ? CalendarClock : type === 'return' ? FileText : type === 'evidence' ? FileCheck2 : type === 'attention' ? AlertTriangle : type === 'calculator' ? Calculator : type === 'policy' ? Landmark : type === 'complete' ? CheckCircle2 : ShieldCheck; const tones: Record<IconType, string> = { health: 'bg-[#e5f4ef] text-[#247269]', liability: 'bg-[#f0edff] text-[#6346e7]', calendar: 'bg-[#fff2d8] text-[#a66b12]', return: 'bg-[#e9f2ff] text-[#376fc3]', evidence: 'bg-[#eaf7f3] text-[#2a806c]', attention: 'bg-[#fff0ea] text-[#c15d38]', calculator: 'bg-[#f1efff] text-[#6749e5]', policy: 'bg-[#e8f4f5] text-[#28727a]', complete: 'bg-[#e7f6ec] text-[#258153]' }; return <span className={`relative grid h-10 w-10 shrink-0 place-items-center rounded-[14px] ${inverse ? 'bg-white text-[#5d42e8]' : tones[type]}`}><Icon className="h-[18px] w-[18px]" strokeWidth={2.15} /><i className={`absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full ${inverse ? 'bg-[#2a9a88]' : 'bg-current opacity-70'}`} /></span> }
function Metric({ icon, label, value, note, tone }: { icon: IconType; label: string; value: string; note: string; tone: 'violet' | 'amber' | 'blue' | 'rose' }) { const toneMap = { violet: 'from-[#f6f3ff] to-white', amber: 'from-[#fff9eb] to-white', blue: 'from-[#f0f6ff] to-white', rose: 'from-[#fff5f2] to-white' }; return <article className={`rounded-[22px] border border-[#273d4a]/10 bg-gradient-to-br ${toneMap[tone]} p-4 shadow-[0_8px_25px_rgba(37,48,43,.035)]`}><FinanceMark type={icon} /><p className="mt-4 text-[10px] font-extrabold uppercase tracking-[.13em] text-[#6c7e87]">{label}</p><p className="mt-1 font-display text-2xl font-semibold tracking-[-.04em] text-[#17353c]">{value}</p><p className="mt-1 text-[11px] leading-4 text-[#718089]">{note}</p></article> }
function SegmentButton({ color, label, value, percent, onClick }: { color: 'violet' | 'teal'; label: string; value: string; percent: number; onClick: () => void }) { return <button type="button" onClick={onClick} className="rounded-xl border border-[#e1e8e9] bg-white p-3 text-left transition hover:border-[#6b4df5]/30"><span className={`inline-block h-2 w-2 rounded-full ${color === 'violet' ? 'bg-[#6b4df5]' : 'bg-[#2c9188]'}`} /><p className="mt-2 text-[11px] font-bold text-[#657681]">{label}</p><div className="mt-1 flex items-center justify-between gap-2"><strong className="text-sm text-[#17353c]">{value}</strong><span className="text-[11px] text-[#7c8b91]">{Math.round(percent * 100)}%</span></div></button> }
function StatusDot({ tone }: { tone: 'good' | 'attention' | 'critical' | 'neutral' }) { return <span className={`inline-flex h-3 w-3 shrink-0 rounded-full border-2 border-white shadow-sm ${tone === 'good' ? 'bg-[#27a477]' : tone === 'attention' ? 'bg-[#eba51e]' : tone === 'critical' ? 'bg-[#df604a]' : 'bg-[#8d9ba1]'}`} /> }
function ReturnBadge({ state, dueDate }: { state: string; dueDate: string }) { const overdue = !['Accepted', 'Acknowledged'].includes(state) && Date.parse(`${dueDate}T00:00:00Z`) < Date.parse(`${today}T00:00:00Z`); const tone = overdue ? 'critical' : ['Accepted', 'Acknowledged'].includes(state) ? 'good' : 'attention'; const label = overdue ? 'Overdue' : state === 'Accepted' ? 'Accepted' : state === 'Acknowledged' ? 'Acknowledged' : state === 'Submitted' ? 'Submitted' : state === 'Prepared' ? 'Prepared' : state.replace(/([A-Z])/g, ' $1').trim(); return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-extrabold ${tone === 'good' ? 'bg-[#e9f6ef] text-[#277653]' : tone === 'critical' ? 'bg-[#fff0eb] text-[#bd523e]' : 'bg-[#fff4dc] text-[#92631a]'}`}><StatusDot tone={tone} />{label}</span> }
function PolicyBadge({ status }: { status: string }) { const good = status === 'APPROVED'; const muted = status === 'RETIRED'; return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-extrabold ${good ? 'bg-[#e9f6ef] text-[#277653]' : muted ? 'bg-[#edf0f1] text-[#63737b]' : 'bg-[#fff4dc] text-[#92631a]'}`}><StatusDot tone={good ? 'good' : muted ? 'neutral' : 'attention'} />{good ? 'Active' : muted ? 'Retired' : 'Draft'}</span> }
function MiniMetric({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-[#f6f8f9] px-3 py-2.5"><p className="text-[9px] font-extrabold uppercase tracking-[.1em] text-[#74848a]">{label}</p><p className="mt-1 text-sm font-extrabold tabular-nums text-[#17353c]">{value}</p></div> }
function ActionButton({ label, onClick }: { label: string; onClick: () => void }) { return <button type="button" onClick={onClick} className="rounded-xl border border-[#d8e0e2] bg-white px-3 py-2 text-xs font-extrabold text-[#263d47] transition hover:border-[#6b4df5]/35 hover:text-[#5d42e8]">{label}</button> }
function SmartEmpty({ type, title, detail, action, onAction }: { type: IconType; title: string; detail: string; action?: string; onAction?: () => void }) { return <div className="rounded-2xl border border-dashed border-[#ccd9dc] bg-[#fbfcfc] p-5 text-center"><FinanceMark type={type} /><p className="mt-3 text-sm font-extrabold text-[#17353c]">{title}</p><p className="mx-auto mt-1 max-w-md text-xs leading-5 text-[#657681]">{detail}</p>{action && onAction ? <button type="button" onClick={onAction} className="mt-3 text-xs font-extrabold text-[#5d42e8]">{action}</button> : null}</div> }
function Field({ label, value, onChange, required, placeholder, type = 'text' }: { label: string; value: string; onChange: (value: string) => void; required?: boolean; placeholder?: string; type?: string }) { return <label className="block text-xs font-bold text-[#53666f]">{label}<input required={required} type={type} value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} className="mt-1 h-10 w-full rounded-xl border border-[#d6dfe3] bg-white px-3 text-sm font-medium text-[#17353c] outline-none transition placeholder:text-[#a4afb5] focus:border-[#6b4df5] focus:ring-2 focus:ring-[#6b4df5]/15" /></label> }
function MoneyField(props: Omit<Parameters<typeof Field>[0], 'type'>) { return <Field {...props} type="number" /> }
function Select({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: Array<[string, string]> }) { return <label className="block text-xs font-bold text-[#53666f]">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="mt-1 h-10 w-full rounded-xl border border-[#d6dfe3] bg-white px-3 text-sm font-medium text-[#17353c] outline-none focus:border-[#6b4df5] focus:ring-2 focus:ring-[#6b4df5]/15">{options.map(([option, name]) => <option key={option} value={option}>{name}</option>)}</select></label> }
function SectionLabel({ children }: { children: ReactNode }) { return <p className="text-[10px] font-extrabold uppercase tracking-[.16em] text-[#597f85]">{children}</p> }
function Row({ label, value, strong = false }: { label: string; value: string; strong?: boolean }) { return <div className="flex items-start justify-between gap-4 text-xs"><span className="text-[#657681]">{label}</span><span className={`max-w-[64%] text-right ${strong ? 'font-extrabold text-[#17353c]' : 'font-bold text-[#43565f]'}`}>{value}</span></div> }
function Choice({ label, detail, selected, disabled }: { label: string; detail: string; selected?: boolean; disabled?: boolean }) { return <div className={`rounded-2xl border p-4 ${selected ? 'border-[#6b4df5] bg-[#f6f3ff]' : 'border-[#dfe6e8] bg-[#fafbfb]'} ${disabled ? 'opacity-55' : ''}`}><div className="flex items-center gap-2"><span className={`grid h-5 w-5 place-items-center rounded-full border ${selected ? 'border-[#6b4df5] bg-[#6b4df5] text-white' : 'border-[#b9c6ca]'}`}>{selected ? <CheckCircle2 className="h-3.5 w-3.5" /> : null}</span><p className="text-sm font-extrabold text-[#17353c]">{label}</p></div><p className="mt-2 pl-7 text-xs leading-5 text-[#657681]">{detail}</p></div> }
function ErrorNotice({ error }: { error: unknown }) { return <p className="rounded-xl bg-rose-50 p-3 text-xs leading-5 text-rose-700">{error instanceof Error ? error.message : 'The statutory action could not be completed.'}</p> }
function Loading() { return <VisualLoadingState title="Preparing statutory controls" detail="We are reading posted liabilities, return readiness, policy versions and recorded evidence for this workspace." icon={ShieldCheck} /> }
function Failure({ message }: { message: string }) { return <div className="rounded-2xl border border-rose-200 bg-rose-50 p-5 text-rose-800"><AlertTriangle className="h-5 w-5" /><p className="mt-3 font-bold">Finance controls unavailable</p><p className="mt-1 text-sm">{message}</p></div> }
function healthPresentation(value: string) { return value === 'ACTION_REQUIRED' ? { tone: 'critical' as const, label: 'Attention required', detail: 'A return or evidence item needs review.' } : value === 'ON_TRACK_WITH_ACTIONS' ? { tone: 'attention' as const, label: 'On track with actions', detail: 'Upcoming work is visible below.' } : { tone: 'good' as const, label: 'Controlled', detail: 'No recorded exception needs attention.' } }
function timelineTone(value: string): 'good' | 'attention' | 'critical' | 'neutral' { return value === 'COMPLETE' ? 'good' : value === 'OVERDUE' ? 'critical' : value === 'DUE_SOON' ? 'attention' : 'neutral' }
function returnStateCopy(state: string, dueState: string) { if (dueState === 'OVERDUE') return 'Past the recorded due date'; if (state === 'Accepted') return 'Accepted with acknowledgement'; if (state === 'Acknowledged') return 'Acknowledgement recorded'; if (state === 'Submitted') return 'Submission recorded; evidence required'; if (state === 'Prepared') return 'Prepared, not filed'; return state.replace(/([A-Z])/g, ' $1').trim() }
